// RUN-REC-BRIDGE-001 — reconstruction minimale WF-SLM-001
// Aucun secret. Aucun log applicatif de prompt/contenu.
// Modèle HUM validé pour reconstruction : llama3.2:3b

const input = $input.first()?.json ?? {};
const body = input.body ?? input;

function cleanString(value) {
  return typeof value === "string" ? value.trim() : "";
}

function reject(errorCode, message) {
  return [{
    json: {
      ok: false,
      contractStatus: "invalid",
      source: "slm",
      errorCode,
      message,
      needsEscalation: false,
      reason: null,
      performance: {
        promptTokens: null,
        outputTokens: null,
        totalTokens: null
      }
    }
  }];
}

const client =
  body.client &&
  typeof body.client === "object" &&
  !Array.isArray(body.client)
    ? body.client
    : {};

if (client.humAuthorized !== true) {
  return reject(
    "hum_authorization_required",
    "Une autorisation HUM explicite est requise."
  );
}

const instruction = cleanString(body.instruction);
const selection = cleanString(body.selection);

if (!instruction && !selection) {
  return reject(
    "missing_input",
    "Une instruction ou une sélection est requise."
  );
}

const page =
  body.page &&
  typeof body.page === "object" &&
  !Array.isArray(body.page)
    ? body.page
    : {};

const prompt = [
  "Tu es le SLM local du BAW HUM Bridge 0.7.1.",
  "Tu fournis une aide textuelle uniquement. Tu n'exécutes aucune action externe.",
  "Réponds strictement selon le schéma JSON fourni.",
  "",
  "Règle d'escalade : needsEscalation=true uniquement si une réponse plus robuste est recommandée",
  "(information externe ou actuelle nécessaire, ambiguïté importante, enjeu sensible, contexte insuffisant,",
  "ou confiance insuffisante). L'escalade reste une recommandation : aucune décision sensible automatique.",
  "",
  `Instruction : ${instruction || "(aucune)"}`,
  "",
  `Sélection : ${selection || "(aucune)"}`,
  "",
  `Contexte de page : ${JSON.stringify(page)}`
].join("\n");

const ollamaBody = JSON.stringify({
  model: "llama3.2:3b",
  prompt,
  format: {
    type: "object",
    properties: {
      answer: { type: "string" },
      needsEscalation: { type: "boolean" },
      reason: { type: "string" }
    },
    required: ["answer", "needsEscalation", "reason"]
  },
  stream: false,
  options: {
    temperature: 0.2
  }
});

return [{
  json: {
    slmStatus: "ready",
    ollamaBody
  }
}];

// Produit le contrat public stable attendu par BAW HUM Bridge 0.7.1.

const data = $input.first()?.json ?? {};

function cleanString(value) {
  return typeof value === "string" ? value.trim() : "";
}

function invalid(errorCode, message) {
  return [{
    json: {
      ok: false,
      contractStatus: "invalid",
      source: "slm",
      errorCode,
      message,
      needsEscalation: false,
      reason: null,
      performance: {
        promptTokens: Number.isFinite(Number(data.prompt_eval_count))
          ? Number(data.prompt_eval_count)
          : null,
        outputTokens: Number.isFinite(Number(data.eval_count))
          ? Number(data.eval_count)
          : null,
        totalTokens: (
          Number.isFinite(Number(data.prompt_eval_count)) &&
          Number.isFinite(Number(data.eval_count))
        )
          ? Number(data.prompt_eval_count) + Number(data.eval_count)
          : null
      }
    }
  }];
}

if (data.error) {
  const message =
    cleanString(data.error?.message) ||
    cleanString(data.error) ||
    "Échec de l'appel Ollama.";

  return invalid("ollama_error", message);
}

const rawContent = cleanString(data.response);

if (!rawContent) {
  return invalid(
    "empty_model_response",
    "Ollama n'a retourné aucun contenu exploitable."
  );
}

let parsed;

try {
  parsed = JSON.parse(rawContent);
} catch {
  return invalid(
    "invalid_model_contract",
    "La réponse du SLM n'est pas un JSON valide."
  );
}

const answer = cleanString(parsed.answer);

if (!answer || typeof parsed.needsEscalation !== "boolean") {
  return invalid(
    "invalid_model_contract",
    "La réponse du SLM ne respecte pas le contrat attendu."
  );
}

const promptTokens = Number(data.prompt_eval_count);
const outputTokens = Number(data.eval_count);

const promptTokensValue =
  Number.isFinite(promptTokens) ? promptTokens : null;

const outputTokensValue =
  Number.isFinite(outputTokens) ? outputTokens : null;

const totalTokensValue =
  promptTokensValue !== null && outputTokensValue !== null
    ? promptTokensValue + outputTokensValue
    : null;

return [{
  json: {
    ok: true,
    contractStatus: "valid",
    source: "slm",
    answer,
    needsEscalation: parsed.needsEscalation === true,
    reason: parsed.needsEscalation === true
      ? (cleanString(parsed.reason) || "Escalade recommandée par le SLM.")
      : null,
    performance: {
      promptTokens: promptTokensValue,
      outputTokens: outputTokensValue,
      totalTokens: totalTokensValue
    }
  }
}];
